	sections = {
		{
			title = "概述",
			text = [=[月溪镇曾是{link:westfall}西部荒野{/link}南部一个繁荣的村庄。它的居民已经不在了。{link:defias-brotherhood}迪菲亚潜行者{/link}夺取了这座小镇，使它成为自己权力的中心，如今空荡荡的房屋里住着盗贼和他们的头目。月溪镇只有一个商人在公开做生意，那是一个迪菲亚商人，谁有钱就卖给谁，什么也不问。小镇之下是战争遗留下来的旧{link:ginro-hearthkindle}金{/link}矿：{link:the-deadmines}死亡矿井{/link}。{link:edwin-vancleef}艾德温·范克里夫{/link}的石匠们守卫着它的入口，因为他们在深处建造的东西是兄弟会最大的秘密。]=],
		},
	},
})

Translate("zhCN", "jangolode-mine", {
	title = "詹戈洛德矿洞",
	aliases = { "詹戈洛德" },
	sections = {
		{
			title = "概述",
			text = [=[詹戈洛德矿洞位于{link:westfall}西部荒野{/link}西北部，在{link:furlbrows-pumpkin-farm}法布隆农场{/link}上方的丘陵中。它曾是向{link:stormwind-city}暴风城{/link}输送矿石的矿洞之一。如今{link:defias-brotherhood}迪菲亚{/link}占据了它，他们的陷阱猎手在矿口周围的土地上游荡。在矿洞里，兄弟会让{link:kobolds}狗头人{/link}替它挖掘。它们在一个同族的挖掘大师手下干活。一些研究过{link:burning-steppes}平原{/link}疾病的人，最初就是在这里、在矿洞的尾矿中寻找病源的。]=],
