Translate("zhCN", "gold-coast-quarry", {
	title = "金海岸矿洞",
	sections = {
		{
			title = "概述",
			text = [=[金海岸矿洞位于{link:westfall}西部荒野{/link}的西缘，{link:burning-steppes}平原{/link}在这里向大海倾斜而下。它曾为王国提供石料和黄{link:ginro-hearthkindle}金{/link}。如今{link:defias-brotherhood}迪菲亚{/link}掠夺者占据了它，{link:riverpaw-gnolls}河爪豺狼人{/link}在它们自己的监工的鞭打下在坑中苦干。{link:gnolls}豺狼人{/link}并不是为自己挖掘。他们是为兄弟会挖掘，在整片平原上，他们已经成了兄弟会的盟友。把掠夺者赶出矿洞，是人民军为那些想加入其行列的人设下的考验之一。]=],
		},
	},
})

Translate("zhCN", "alexston-farmstead", {
	title = "阿历克斯顿农场",
	sections = {
		{
			title = "概述",
			text = [=[阿历克斯顿农场是{link:westfall}西部荒野{/link}中部的老家庭农场之一。它的主人一家已经逃走，田地落入了{link:harvest-golems}收割傀儡{/link}之手，它们仍在田垄间行走，仿佛有庄稼等着收割。成群的{link:defias-brotherhood}迪菲亚{/link}掠夺者和抢劫者在矿洞与{link:moonbrook}月溪镇{/link}之间往来时穿过这座农场，把最后的主人留下的东西统统拿走。把他们清出农场，是人民军为想要加入的人设下的首批任务之一。]=],
		},
	},
})

Translate("zhCN", "saldeans-farm", {
