Translate("zhCN", "furlbrows-pumpkin-farm", {
	title = "法布隆南瓜农场",
	aliases = { "法布隆农场" },
	sections = {
		{
			title = "概述",
			text = [=[法布隆南瓜农场位于{link:westfall}西部荒野{/link}北部，靠近{link:jangolode-mine}詹戈洛德矿洞{/link}。它属于西奥多和{link:verna-furlbrow}弗娜·法布隆{/link}，直到那天夜里他们的田地里挤满了盗贼。{link:farmer-furlbrow}法布隆{/link}夫妇逃得如此匆忙，以至于西奥多把他最珍贵的财物，一块怀表，落在了农舍的衣柜里。{link:defias-brotherhood}迪菲亚{/link}夺走了农场，连同它的地契。如今南瓜在田里腐烂，{link:harvest-golems}收割傀儡{/link}守护着一片永远不会有人收获的庄稼。]=],
		},
	},
})

Translate("zhCN", "the-dagger-hills", {
	title = "匕首岭",
	aliases = { "匕首丘陵" },
	sections = {
		{
			title = "概述",
			text = [=[匕首岭是{link:westfall}西部荒野{/link}南部崎岖的{link:razorfen-downs}高地{/link}，位于{link:moonbrook}月溪镇{/link}后方，俯瞰大海。兄弟会最凶悍的战士在这里扎营：拦路抢劫的强盗，熟悉每一条小径的潜行者，以及用拳头解决争端的打手。人民军相信，逃脱巡逻的{link:defias-brotherhood}迪菲亚{/link}袭击者会躲进这些山中，筹划下一次袭击。在山岭的另一侧，靠近水边，一条隐秘的路从{link:the-deadmines}死亡矿井{/link}深处通出来。只有穿过矿井的人才知道它在哪里。]=],
		},
	},
})

Translate("zhCN", "westfall-lighthouse", {
	title = "西部荒野灯塔",
	aliases = { "灯塔" },
	sections = {
		{
			title = "概述",
			text = [=[西部荒野灯塔矗立在这片土地的西南角，下方的礁石曾撞碎过许多船只。灯塔看守人和他的家人曾经照看着灯火。海岸的{link:murlocs}鱼人{/link}两次前来攻击他们，率领它们的是一个名叫{link:old-murk-eye}老瞎眼{/link}的大鱼人。第一次，这家人逃走了，灯火熄灭，当夜一位船长死在了礁石上。第二次，这家人没能逃脱。灯火至今仍在燃烧，因为那位溺亡的船长不会让它熄灭。]=],
		},
	},
})

Translate("zhCN", "the-dead-acre", {
	title = "死亡农地",
	aliases = { "死亡之地" },
	sections = {
		{
			title = "概述",
			text = [=[死亡农地位于{link:westfall}西部荒野{/link}东南部，靠近通往{link:duskwood}暮色森林{/link}的桥。它曾是一座和其他农场一样的农场。兄弟会到来时，房屋和田地都被付之一炬，只剩下烧焦的废墟。在它冒烟的田垄间行走的{link:harvest-golems}收割机器{/link}是西部荒野最危险的，那是任何农民都不敢靠近的巨型收割者。{link:defias-brotherhood}迪菲亚{/link}强盗在焚毁的建筑间放哨。关于曾经住在这里的那户人家，没有留下任何记载。]=],
