Translate("zhCN", "the-molsen-farm", {
	title = "摩尔森农场",
	aliases = { "摩尔森家的农场" },
	sections = {
		{
			title = "概述",
			text = [=[摩尔森农场是{link:westfall}西部荒野{/link}北部被遗弃的农庄之一。主人一家已经不在，有人看见{link:defias-brotherhood}迪菲亚{/link}陷阱猎手在它的田地周围出没。农场的井仍然出水，但水已不再干净。检测过井水的人发现，里面的{link:ginro-hearthkindle}金{/link}属本该出现在冶炼炉里，而不是农夫的水桶里。不管是什么在毒害西部荒野的土壤，它已经到达了摩尔森的井，并且正从别处穿过地下蔓延开来。]=],
		},
	},
})

Translate("zhCN", "the-jansen-stead", {
	title = "贾森农场",
	aliases = { "贾森家的农场" },
	sections = {
		{
			title = "概述",
			text = [=[贾森农场是{link:westfall}西部荒野{/link}最北边的农场，靠近跨入{link:elwynn-forest}艾尔文森林{/link}的那座桥。它是从{link:stormwind-city}暴风城{/link}来的旅人看到的第一座农场，也是这片土地衰败到何种地步的第一个迹象。它的主人像许多人一样被赶走了，{link:harvest-golems}收割傀儡{/link}和{link:defias-brotherhood}迪菲亚{/link}占据着田地。在路边，{link:farmer-furlbrow}法布隆{/link}夫妇守在他们坏掉的马车旁，等待永远离开西部荒野的机会。人们发现，这座农场的井和{link:the-molsen-farm}摩尔森农场{/link}的井一样带着毒。]=],
		},
	},
})

Translate("zhCN", "longshore", {
	title = "长滩",
	sections = {
		{
			title = "概述",
			text = [=[长滩是{link:westfall}西部荒野{/link}漫长的西海岸，一片紧邻无尽之海的沙石海滩。许多船只的残骸半埋在沙中，散布在海岸上。这片海岸属于{link:murlocs}鱼人{/link}。它们的村落挤满了海滩，它们的袭击者会攻击任何在岸边行走的人。其中最可怕的是{link:old-murk-eye}老瞎眼{/link}，它曾率领鱼人攻击{link:westfall-lighthouse}西部荒野灯塔{/link}。在残骸之间，一只生锈的锚标出了一个地方，据说溺亡的杉德尔船长在那里留下了通往他宝藏的第一条线索。]=],
		},
	},
})

Translate("zhCN", "gryan-stoutmantle", {
	title = "治安官格里安·斯托曼",
	subtitle = "人民军领袖",
	found = "哨兵岭塔顶",
	hint = "登上哨兵岭的塔楼，与人民军的领袖交谈。",
	allegiance = "人民军",
	aliases = { "斯托曼", "斯托曼大人" },
	sections = {
		{
			title = "概述",
			text = [=[治安官格里安·斯托曼在{link:sentinel-hill}哨兵岭{/link}的瞭望塔上领导着人民军。他从{link:lordaeron}洛丹伦{/link}被污染的土地归来，却发现故乡已被盗贼占据，被国王遗忘。他没有等待援助。他召集了那些不肯离开的农民，给他们武器，让他们以{link:holy-light}圣光{/link}之名发誓保卫{link:westfall}西部荒野{/link}。]=],
		},
		{
			title = "意义",
			text = [=[斯托曼代表着平凡百姓对一个抛弃了他们的王国的回答。揭开{link:defias-brotherhood}迪菲亚潜行者{/link}真相、并把其首领追剿到巢穴的，是他的人民军，而不是{link:stormwind-city}暴风城{/link}的军队。]=],
		},
		{
